import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :eventpage, EventpageWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# Force using SSL in production. This also sets the "strict-security-transport" header,
# known as HSTS. Note `:force_ssl` is required to be set at compile-time.
#
# SaaS Custom Domains terminates TLS and talks to Phoenix with
# X-Forwarded-Proto: https. Without rewrite_on, every
# request looks like HTTP and Plug.SSL redirects customers to
# https://<your url host>/..., away from their own domain.
#
# Health checks (and, locally, webhooks from the mock) come from machines
# on internal addresses over plain HTTP, so they're excluded. FORCE_SSL=false
# turns the redirect off for local runs over plain HTTP (docker compose).
config :eventpage, EventpageWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [
      paths: ["/up", "/api/webhooks/saascustomdomains"],
      hosts: ["localhost", "127.0.0.1"],
      conn: {EventpageWeb.HealthCheck, :skip_https_redirect?, []}
    ]
  ]

# Do not print debug messages in production
config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
